// Server-side: trigger an event
import Pusher from 'pusher';

const pusher = new Pusher({
  appId: process.env.PUSHER_APP_ID!,
  key: process.env.PUSHER_KEY!,
  secret: process.env.PUSHER_SECRET!,
  cluster: process.env.PUSHER_CLUSTER!,
  useTLS: true,
});

// Trigger 'new-order' event on 'orders' channel
await pusher.trigger('orders', 'new-order', {
  orderId: 'order_123',
  customerName: 'Jane Smith',
  amount: 49.99,
});

console.log('Event triggered');

// Client-side (browser/React)
import PusherClient from 'pusher-js';

const pusher = new PusherClient(process.env.NEXT_PUBLIC_PUSHER_KEY!, {
  cluster: process.env.NEXT_PUBLIC_PUSHER_CLUSTER!,
});

const channel = pusher.subscribe('orders');

channel.bind('new-order', (data: { orderId: string; customerName: string; amount: number }) => {
  console.log('New order received:', data);
  // Update UI in real-time
});

// Clean up on component unmount
return () => {
  channel.unbind_all();
  pusher.unsubscribe('orders');
};
